    #[test]
    fn shared_nothing_routing_tag_matches_redis_cluster_rules() {
        assert_eq!(crate::redis_routing_tag(b"{tenant}:string"), b"tenant");
        assert_eq!(crate::redis_routing_tag(b"prefix{tenant}:hash"), b"tenant");
        assert_eq!(crate::redis_routing_tag(b"{}:empty"), b"{}:empty");
        assert_eq!(crate::redis_routing_tag(b"{unterminated"), b"{unterminated");
        assert_eq!(crate::redis_routing_tag(b"plain"), b"plain");

        let worker_count = 32;
        let keys: [&[u8]; 3] = [b"{tenant}:string", b"{tenant}:list", b"{tenant}:hash"];
        assert!(
            keys.iter()
                .all(|key| crate::sharded_set_get_shard(key, worker_count)
                    == crate::sharded_set_get_shard(keys[0], worker_count))
        );
    }

    #[test]
    fn reactor_single_key_commands_admit_only_partition_local_work() {
        for command in [
            b"GET".as_slice(),
            b"SET",
            b"LRANGE",
            b"HGETALL",
            b"LLEN",
            b"HLEN",
            b"BITCOUNT",
            b"strlen",
            b"SADD",
            b"SCARD",
            b"SISMEMBER",
            b"SMISMEMBER",
            b"SMEMBERS",
            b"SREM",
            // The families the reactor path could not serve at all before.
            b"BITPOS",
            b"bitfield_ro",
            b"SETBIT",
            b"ZADD",
            b"ZRANGEBYSCORE",
            b"zremrangebyscore",
            b"ZCOUNT",
            b"ZSCORE",
            b"ZSCAN",
            b"HMGET",
            b"HSCAN",
            b"LPOS",
            b"RPUSH",
            b"LTRIM",
            b"SSCAN",
            b"TTL",
            b"EXPIRE",
            // HLL and geo, the families the table had no entry for at all.
            b"PFADD",
            b"pfadd",
            b"GEOADD",
            b"GEODIST",
            b"GEOHASH",
            b"GEOPOS",
            b"GEOSEARCH",
            b"GEORADIUS_RO",
            // 20 bytes: the longest name in the table, and the one that the
            // case-fold buffer silently rejected before it was widened.
            b"GEORADIUSBYMEMBER_RO",
            b"georadiusbymember_ro",
        ] {
            assert!(
                crate::reactor_single_key_command(command),
                "{command:?} stays on one keyspace partition"
            );
        }

        for command in [
            b"SMOVE".as_slice(),
            b"MGET",
            b"SINTER",
            b"SORT",
            b"EVAL",
            // Multi-key writes that would reach outside the locked partition.
            b"ZRANGESTORE",
            b"ZUNIONSTORE",
            b"BITOP",
            b"SINTERCARD",
            b"RPOPLPUSH",
            b"COPY",
            // Key at argv[2], so routing on argv[1] would lock the wrong one.
            b"OBJECT",
            b"MEMORY",
            // Nondeterministic member selection.
            b"SPOP",
            b"SRANDMEMBER",
            b"ZRANDMEMBER",
            b"HRANDFIELD",
            // Would park a whole reactor.
            b"BLPOP",
            b"BZPOPMIN",
            // Cross-partition by construction.
            b"KEYS",
            b"SCAN",
            b"DBSIZE",
            b"FLUSHDB",
            b"RANDOMKEY",
            b"MOVE",
            // Admitted nowhere until their payloads are pinned against 7.2.4.
            b"DUMP",
            b"RESTORE",
            // Write a SECOND key that admission cannot see from the name.
            b"PFMERGE",
            b"GEOSEARCHSTORE",
            b"GEORADIUS",
            b"GEORADIUSBYMEMBER",
        ] {
            assert!(
                !crate::reactor_single_key_command(command),
                "{command:?} is not safe or reachable as partition-local work"
            );
        }
        assert!(
            !crate::sharded_single_key_command(b"BITCOUNT"),
            "the older handoff pool must keep its closed command family"
        );

        // The variadic key-list commands are partition-local at exactly one key
        // and cross-partition at two, so admission has to read argc, not just
        // the name. A two-key DEL admitted here would delete only whichever key
        // happened to live in the partition argv[1] routed to.
        for name in [
            b"DEL".as_slice(),
            b"UNLINK",
            b"EXISTS",
            b"TOUCH",
            b"PFCOUNT",
        ] {
            assert!(
                !crate::reactor_single_key_command(name),
                "{name:?} must not be admitted on its name alone"
            );
            assert!(
                crate::reactor_partition_local_command(&[name, b"k"]),
                "{name:?} over one key stays on one partition"
            );
            assert!(
                !crate::reactor_partition_local_command(&[name, b"k1", b"k2"]),
                "{name:?} over two keys reaches outside the locked partition"
            );
            assert!(
                crate::reactor_partition_local_command(&[name]),
                "{name:?} with no key must reach the partition's own arity error"
            );
        }
        assert!(
            !crate::reactor_partition_local_command(&[]),
            "an empty command is not partition-local work"
        );
        assert!(
            crate::reactor_partition_local_command(&[b"ZADD", b"k", b"1", b"m"]),
            "argc must not narrow the fixed-key commands"
        );
    }

    /// (frankenredis-4m3i4) The memo only pays if the key is a function of the
    /// packet SHAPE and nothing else. A key that moved with the arguments would
    /// allocate a fresh slot per distinct key name and never hit, which is a
    /// silent loss of the whole lever — no reply changes, so only this test
    /// would catch it.
    #[test]
    fn borrowed_fast_route_key_depends_on_the_shape_and_not_the_arguments() {
        let short = crate::borrowed_fast_route_key(b"*4\r\n$5\r\nLTRIM\r\n$1\r\nl\r\n$1\r\n0\r\n")
            .expect("shape A key");
        let long = crate::borrowed_fast_route_key(
            b"*4\r\n$5\r\nLTRIM\r\n$24\r\nsome:much:longer:key:aaa\r\n",
        )
        .expect("shape A key");
        assert_eq!(
            short, long,
            "the key must not move with the argument that follows the name"
        );

        let mixed_case =
            crate::borrowed_fast_route_key(b"*4\r\n$5\r\nlTrIm\r\n$1\r\nl\r\n$1\r\n0\r\n")
                .expect("mixed-case LTRIM key");
        assert_eq!(
            short, mixed_case,
            "case-insensitive command dispatch must share one miss-memo shape"
        );

        // Same arity and name length, different name.
        let lrem = crate::borrowed_fast_route_key(b"*4\r\n$4\r\nLREM\r\n$1\r\nl\r\n$1\r\n1\r\n")
            .expect("LREM key");
        let hdel = crate::borrowed_fast_route_key(b"*4\r\n$4\r\nHDEL\r\n$1\r\nh\r\n$1\r\nf\r\n")
            .expect("HDEL key");
        assert_ne!(lrem, hdel, "same arity and length, different command");

        // Same name, different arity.
        let rpush3 = crate::borrowed_fast_route_key(b"*3\r\n$5\r\nRPUSH\r\n$1\r\nl\r\n$1\r\na\r\n")
            .expect("RPUSH/3 key");
        let rpush4 = crate::borrowed_fast_route_key(b"*4\r\n$5\r\nRPUSH\r\n$1\r\nl\r\n$1\r\na\r\n")
            .expect("RPUSH/4 key");
        assert_ne!(rpush3, rpush4, "arity is part of the shape");

        // Shape B: a two-digit name length puts the name one byte later.
        let by_score =
            crate::borrowed_fast_route_key(b"*4\r\n$13\r\nZRANGEBYSCORE\r\n$1\r\nz\r\n$1\r\n0\r\n")
                .expect("shape B key");
        let by_lex =
            crate::borrowed_fast_route_key(b"*4\r\n$11\r\nZRANGEBYLEX\r\n$1\r\nz\r\n$1\r\n-\r\n")
                .expect("shape B key");
        assert_ne!(by_score, by_lex, "two-digit-length names must separate");
        assert_ne!(
            by_score, short,
            "a shape-B key must not collide with a shape-A one"
        );

        // Anything not fully understood declines, which costs pruning and never
        // correctness.
        assert!(crate::borrowed_fast_route_key(b"*2\r\n$3\r\nGET\r\n").is_none());
        assert!(crate::borrowed_fast_route_key(b"+OK\r\n").is_none());
        assert!(crate::borrowed_fast_route_key(b"*x\r\n$5\r\nLTRIM\r\n$1\r\nl\r\n").is_none());
    }

    /// The memo must answer "known miss" ONLY for the key currently in the slot.
    /// A stale true would route a packet to the generic path forever after an
    /// eviction — still correct, but it is the difference between a cache and a
    /// blanket bypass, so it is pinned.
    #[test]
    fn borrowed_route_memo_reports_only_the_key_it_holds() {
        let mut memo = [0u64; crate::BORROWED_ROUTE_MEMO_SLOTS];
        let ltrim = crate::borrowed_fast_route_key(b"*4\r\n$5\r\nLTRIM\r\n$1\r\nl\r\n$1\r\n0\r\n")
            .expect("LTRIM key");
        let lrem = crate::borrowed_fast_route_key(b"*4\r\n$4\r\nLREM\r\n$1\r\nl\r\n$1\r\n1\r\n")
            .expect("LREM key");

        assert!(!crate::borrowed_route_is_known_miss(&memo, ltrim));
        crate::record_borrowed_route_miss(&mut memo, ltrim);
        assert!(crate::borrowed_route_is_known_miss(&memo, ltrim));
        assert!(!crate::borrowed_route_is_known_miss(&memo, lrem));

        // Evicting the slot must retract the old answer rather than keep it.
        let slot = crate::borrowed_route_memo_slot(ltrim);
        memo[slot] = lrem;
        assert!(!crate::borrowed_route_is_known_miss(&memo, ltrim));

        // A zero key is the empty marker, so a real key must never be zero —
        // otherwise a fresh memo would claim to hold it.
        assert!(!crate::borrowed_route_is_known_miss(
            &[0u64; crate::BORROWED_ROUTE_MEMO_SLOTS],
            ltrim
        ));
        assert_ne!(ltrim, 0, "0 is the empty-slot marker");
        assert_ne!(lrem, 0, "0 is the empty-slot marker");
    }

    /// (frankenredis-zwtqi) The per-KEY `ShardedSetGetPool` is unreachable: the
    /// `--experimental-sharded-set-get-workers` flag returns into
    /// `run_shared_nothing_server` long before the pool is built, so the pool is
    /// always `None` and this drain returns at its first line on every pass of
    /// every configuration.
    ///
    /// That is worth a test rather than only the comment at the construction site,
    /// because the deadness is what makes the code DANGEROUS rather than merely
    /// unused: two plausible dispatch designs sit in this file, the dead one routes
    /// KEYS (crc16_slot % workers) and the live one routes CONNECTIONS (round-robin
    /// at accept), and modelling the server on the dead one is what produced the
    /// stale hot-shard invariant that cost frankenredis-uiqc5 a full sweep abort.
    /// I nearly spent a turn optimising this drain's body before checking whether
    /// it runs.
    ///
    /// This pins the half that IS expressible as a unit test: given no pool, the
    /// drain must be a no-op and must not touch the client map. The other half —
    /// that the flag can never leave a pool here — is enforced by the debug_assert
    /// at the construction site.
    #[test]
    fn dead_per_key_sharded_pool_drain_is_a_noop_without_a_pool() {
        let mut clients: crate::ClientMap = crate::ClientMap::default();
        let mut runtime = Runtime::default_strict();
        let mut poll = mio::Poll::new().expect("poll");
        let mut write_tokens = crate::TokenSet::default();
        let mut closing_tokens = crate::TokenSet::default();
        let mut deferred_tokens = crate::TokenSet::default();
        let mut staging = crate::ShardedTickStaging::new(1);

        crate::drain_sharded_set_get_completions(
            None,
            &mut clients,
            &mut runtime,
            &mut poll,
            &mut write_tokens,
            &mut closing_tokens,
            &mut deferred_tokens,
            0,
            None,
            &mut staging,
        );

        assert!(clients.is_empty(), "a poolless drain must touch no client");
        assert!(
            write_tokens.is_empty() && closing_tokens.is_empty() && deferred_tokens.is_empty(),
            "a poolless drain must arm no token set"
        );
    }

    /// (frankenredis-4m3i4) The cascade bypass is a MEASUREMENT arm. Shipping a
    /// build where it is live would route every `*` packet past every borrowed
    /// fast path, which is a silent whole-server slowdown that no reply differs
    /// on — so nothing else in the suite could catch it. Without the
    /// `perf-ab-cascade-bypass` feature the accessor is a `const fn` returning
    /// false, so this also pins that the measurement code is compiled OUT rather
    /// than merely defaulting to off at runtime.
    #[test]
    #[cfg(not(feature = "perf-ab-cascade-bypass"))]
    fn borrowed_cascade_bypass_is_compiled_out_of_production_builds() {
        assert!(
            !crate::borrowed_cascade_bypass_enabled(),
            "the measurement bypass must never be live in a build without its feature"
        );
        const {
            assert!(
                !crate::borrowed_cascade_bypass_enabled(),
                "the accessor must fold at compile time, not read an env var per packet"
            );
        }
    }

    /// (frankenredis-91rts) The aggregate lane is separate from the
    /// partition-local lane, and the separation is the point: a command answered
    /// from one partition when it needs all of them returns a fraction of the
    /// truth, which is worse than refusing.
    #[test]
    fn cross_partition_aggregate_admission_is_narrow() {
        for name in [b"DBSIZE".as_slice(), b"INFO", b"dbsize", b"info"] {
            assert!(
                crate::reactor_cross_partition_aggregate_command(&[name]),
                "{name:?} must reach the whole-keyspace aggregate"
            );
            assert!(
                !crate::reactor_partition_local_command(&[name]),
                "{name:?} must never be answered from a single partition"
            );
        }

        // Wrong-arity DBSIZE is still admitted so a partition's own dispatcher
        // produces Redis's arity error instead of the unsupported reply masking
        // it -- the same convention the bare-DEL case above relies on.
        assert!(
            crate::reactor_cross_partition_aggregate_command(&[b"DBSIZE", b"extra"]),
            "a wrong-arity DBSIZE must reach the real arity error"
        );

        // The other whole-keyspace commands stay refused. Each needs something
        // the snapshot alone cannot give -- a merged cursor, all-or-nothing
        // mutation, or cardinality-weighted choice -- so admitting them here
        // would ship a wrong answer, not a missing one.
        for name in [
            b"KEYS".as_slice(),
            b"SCAN",
            b"FLUSHDB",
            b"FLUSHALL",
            b"RANDOMKEY",
            b"MOVE",
            b"SELECT",
            b"SWAPDB",
        ] {
            assert!(
                !crate::reactor_cross_partition_aggregate_command(&[name]),
                "{name:?} is not answerable from a read-only partition snapshot"
            );
        }
        assert!(
            !crate::reactor_cross_partition_aggregate_command(&[]),
            "an empty command is not an aggregate"
        );
    }

    /// INFO is admitted by name but only the Keyspace section can actually be
    /// aggregated; every other section is backed by reactor-local state that no
    /// other reactor can read. A classifier that accepted the bare form would
    /// emit a full-looking INFO describing one reactor.
    #[test]
    fn info_aggregate_serves_every_section_in_upstream_order() {
        use crate::ReactorInfoRequest;

        let classify = |args: &[&[u8]]| crate::classify_reactor_info_request(args);
        let sections = |request: &[&[u8]]| match classify(request) {
            ReactorInfoRequest::Sections(s) => s,
            other => panic!("{request:?} should be servable, got {other:?}"),
        };

        // Every SERVED section is individually servable.
        for name in crate::REACTOR_INFO_SECTIONS {
            assert_eq!(
                sections(&[b"INFO", name.as_bytes()]),
                vec![*name],
                "{name} must be servable on its own"
            );
        }

        // Case-insensitive and repetition-tolerant.
        assert_eq!(
            sections(&[b"INFO", b"CLIENTS", b"clients"]),
            vec!["clients"]
        );

        // Multi-section requests come back in UPSTREAM order regardless of how
        // the client ordered them; a client parsing positionally depends on it.
        assert_eq!(
            sections(&[b"INFO", b"keyspace", b"server"]),
            vec!["server", "keyspace"]
        );
        assert_eq!(
            sections(&[b"INFO", b"keyspace", b"clients", b"memory"]),
            vec!["clients", "memory", "keyspace"],
            "upstream emits clients, then memory, then keyspace last"
        );

        // Bare INFO is upstream's `default`, which EXCLUDES commandstats and
        // latencystats even though both are servable -- including them would make
        // bare INFO diverge from a real 7.2.4 server.
        assert_eq!(
            sections(&[b"INFO"]),
            crate::REACTOR_DEFAULT_INFO_SECTIONS.to_vec()
        );
        assert_eq!(
            sections(&[b"INFO", b"default"]),
            crate::REACTOR_DEFAULT_INFO_SECTIONS.to_vec()
        );

        // The gap stays named. commandstats and latencystats are NOT served, and
        // `all`/`everything` imply both, so all four forms are refused WHOLE.
        for request in [
            [b"INFO".as_slice(), b"all"].as_slice(),
            &[b"INFO", b"everything"],
            &[b"INFO", b"commandstats"],
            &[b"INFO", b"latencystats"],
            &[b"INFO", b"server", b"commandstats"],
        ] {
            assert_eq!(
                classify(request),
                ReactorInfoRequest::NotAggregatable,
                "{request:?} names a section this path does not serve"
            );
        }
        for unserved in crate::REACTOR_UNSERVED_INFO_SECTIONS {
            assert!(
                !crate::REACTOR_INFO_SECTIONS.contains(unserved),
                "{unserved} is listed as both served and unserved"
            );
        }

        // An unrecognised name still fails closed: a section added upstream later
        // must not be answered with one partition's view just because it parsed.
        assert_eq!(
            classify(&[b"INFO", b"nosuchsection"]),
            ReactorInfoRequest::NotAggregatable
        );
        assert_eq!(
            classify(&[b"INFO", b"server", b"nosuchsection"]),
            ReactorInfoRequest::NotAggregatable,
            "a mixed request is refused whole when any member is unrecognised"
        );

        // The default set must be a subset of the full set, or bare INFO would
        // ask for a section the renderer does not know how to aggregate.
        for name in crate::REACTOR_DEFAULT_INFO_SECTIONS {
            assert!(crate::REACTOR_INFO_SECTIONS.contains(name), "{name}");
        }
    }

    /// The rendered section has to be byte-identical to what a single-node INFO
    /// Keyspace emits, including which databases appear at all.
    #[test]
    fn aggregate_keyspace_section_matches_upstream_shape() {
        assert_eq!(
            crate::render_aggregate_keyspace_section(&[(3, 2, 1_000)]),
            b"# Keyspace\r\ndb0:keys=3,expires=2,avg_ttl=500\r\n".to_vec(),
            "avg_ttl is the expires-weighted mean, not a sum"
        );

        // A database with no keys is omitted entirely, and that decision is made
        // on the SUM: were it made per partition, db0 would vanish from a server
        // whose partition 0 happened to be empty.
        assert_eq!(
            crate::render_aggregate_keyspace_section(&[(0, 0, 0)]),
            b"# Keyspace\r\n".to_vec(),
            "an empty database must not be reported"
        );
        assert_eq!(
            crate::render_aggregate_keyspace_section(&[(0, 0, 0), (5, 0, 0)]),
            b"# Keyspace\r\ndb1:keys=5,expires=0,avg_ttl=0\r\n".to_vec(),
            "a populated database must be reported even when db0 is empty"
        );

        // No volatile keys means no TTL to average, and the weighted mean must
        // not divide by zero.
        assert_eq!(
            crate::render_aggregate_keyspace_section(&[(4, 0, 0)]),
            b"# Keyspace\r\ndb0:keys=4,expires=0,avg_ttl=0\r\n".to_vec()
        );
    }

    /// (frankenredis-zydmi) The per-reactor slots are the whole mechanism: each
    /// reactor publishes only its own, and the server-wide value is their sum.
    /// The discriminating case is that ANY single slot is not the answer --
    /// reading one reactor is exactly the bug this replaces.
    #[test]
    fn reactor_stats_sum_every_slot() {
        let stats = crate::ReactorStats::new(4);
        let per_reactor = [
            crate::ReactorStatsSnapshot {
                connected_clients: 3,
                total_connections_received: 10,
                net_input_bytes: 100,
                net_output_bytes: 200,
            },
            crate::ReactorStatsSnapshot {
                connected_clients: 5,
                total_connections_received: 20,
                net_input_bytes: 300,
                net_output_bytes: 400,
            },
            crate::ReactorStatsSnapshot {
                connected_clients: 0,
                total_connections_received: 7,
                net_input_bytes: 0,
                net_output_bytes: 11,
            },
            crate::ReactorStatsSnapshot {
                connected_clients: 1,
                total_connections_received: 1,
                net_input_bytes: 2,
                net_output_bytes: 3,
            },
        ];
        for (worker, snapshot) in per_reactor.iter().enumerate() {
            stats.publish(worker, snapshot);
        }

        let total = stats.aggregate();
        assert_eq!(total.connected_clients, 9);
        assert_eq!(total.total_connections_received, 38);
        assert_eq!(total.net_input_bytes, 402);
        assert_eq!(total.net_output_bytes, 614);
        for snapshot in &per_reactor {
            assert_ne!(
                snapshot.connected_clients, total.connected_clients,
                "no single reactor holds the server-wide count; reading one is the bug"
            );
        }

        // Republishing replaces a slot rather than accumulating into it -- the
        // reactor publishes absolute totals every tick, so a summing store would
        // inflate without bound over the life of the process.
        stats.publish(
            0,
            &crate::ReactorStatsSnapshot {
                connected_clients: 3,
                total_connections_received: 10,
                net_input_bytes: 100,
                net_output_bytes: 200,
            },
        );
        assert_eq!(
            stats.aggregate().connected_clients,
            9,
            "a repeated publish of the same totals must not change the sum"
        );

        // A reactor that never publishes contributes zero rather than corrupting
        // the total, which is what makes the read wait-free: a wedged reactor
        // cannot block or poison the aggregate.
        let silent = crate::ReactorStats::new(3);
        silent.publish(
            1,
            &crate::ReactorStatsSnapshot {
                connected_clients: 4,
                total_connections_received: 4,
                net_input_bytes: 0,
                net_output_bytes: 0,
            },
        );
        assert_eq!(silent.aggregate().connected_clients, 4);
    }

    /// The weighted mean is what makes the aggregate exact rather than
    /// approximate, so pin the case a plain mean-of-means would get wrong.
    #[test]
    fn aggregate_avg_ttl_weights_by_expiring_key_count() {
        // Partition A: 1 volatile key at 100ms. Partition B: 9 at 1000ms.
        // Weighted: (1*100 + 9*1000) / 10 = 910. A plain mean of the two
        // partition means would report 550.
        let partitions: [(u128, u128); 2] = [(100, 1), (1000, 9)];
        let weighted_sum: u128 = partitions
            .iter()
            .map(|(avg_ttl, expires)| avg_ttl * expires)
            .sum();
        assert_eq!(
            crate::render_aggregate_keyspace_section(&[(10, 10, weighted_sum)]),
            b"# Keyspace\r\ndb0:keys=10,expires=10,avg_ttl=910\r\n".to_vec(),
            "a mean of partition means would report 550 here"
        );
    }

    #[test]
    fn sharded_reply_order_holds_out_of_order_completions() {
        let mut order = ShardedReplyOrder::default();
        order.note_enqueued(3);
        assert_eq!(order.outstanding(), 3);
        let mut out = Vec::new();

        assert!(order.complete_remote(1, b"second".to_vec(), &mut out));
        assert!(out.is_empty(), "sequence one must wait for sequence zero");
        assert_eq!(
            order.outstanding(),
            3,
            "out-of-order replies must remain part of the per-client bound"
        );
        assert!(order.complete_remote(0, b"first".to_vec(), &mut out));
        assert_eq!(out, b"firstsecond");
        assert_eq!(order.outstanding(), 1);
        assert!(order.complete_remote(2, b"third".to_vec(), &mut out));
        assert_eq!(out, b"firstsecondthird");
        assert!(order.is_idle());
        assert!(
            !order.complete_remote(2, b"duplicate".to_vec(), &mut out),
            "a completion without an in-flight command must fail closed"
        );
        assert_eq!(out, b"firstsecondthird");
    }

    /// The direct inverse of the assertion this test used to make.
    ///
    /// It previously asserted that the parser STOPS at a shard change, consuming
    /// 16 of 17 commands. That break was the batch-collapse defect: with W shards
    /// and scattered keys the expected run length is W/(W-1), so the envelope the
    /// design depends on never filled. The parser now consumes the whole pipeline
    /// and routes each command to its own shard's staging buffer.
    #[test]
    fn sharded_parser_stages_across_a_shard_change_instead_of_stopping() {
        const GET_A: &[u8] = b"*2\r\n$3\r\nGET\r\n$1\r\na\r\n";
        const GET_B: &[u8] = b"*2\r\n$3\r\nGET\r\n$1\r\nb\r\n";
        let mut pipeline = GET_A.repeat(16);
        pipeline.extend_from_slice(GET_B);
        let worker_count = 8;
        let shard_a = crate::sharded_set_get_shard(b"a", worker_count);
        let shard_b = crate::sharded_set_get_shard(b"b", worker_count);
        assert_ne!(
            shard_a, shard_b,
            "fixture keys must route to different workers"
        );

        let mut staging = crate::ShardedTickStaging::new(worker_count);
        let parsed = crate::parse_sharded_set_get_batch(
            &pipeline,
            &ParserConfig::default(),
            crate::ShardedSetGetBatchParse {
                token: Token(71),
                first_sequence: 41,
                now_ms: 1,
                worker_count,
                command_limit: crate::MAX_FRAMES_PER_CLIENT_TICK,
            },
            &mut staging,
        )
        .expect("parse a pipeline that crosses a shard boundary");

        assert_eq!(parsed.staged, 17, "every command is consumed, not just 16");
        assert_eq!(parsed.consumed, pipeline.len());
        assert_eq!(parsed.first_command_consumed, GET_A.len());
        assert_eq!(parsed.staged_per_shard[shard_a], 16);
        assert_eq!(parsed.staged_per_shard[shard_b], 1);

        // Sequence numbers stay dense and monotonic in ARRIVAL order across the
        // shard change; that is what lets ShardedReplyOrder restore pipeline
        // reply order regardless of which shard completes first.
        let a_seqs: Vec<u64> = staging.per_shard[shard_a]
            .iter()
            .map(|job| job.sequence)
            .collect();
        assert_eq!(a_seqs, (41..57).collect::<Vec<u64>>());
        assert_eq!(staging.per_shard[shard_b][0].sequence, 57);
        assert!(
            staging.per_shard[shard_a]
                .iter()
                .all(|job| job.command.key() == b"a")
        );
        assert_eq!(staging.per_shard[shard_b][0].command.key(), b"b");
    }

    #[test]
    fn sharded_parser_batches_standard_single_key_mix() {
        const SET: &[u8] = b"*3\r\n$3\r\nSET\r\n$1\r\nk\r\n$2\r\n41\r\n";
        const INCR: &[u8] = b"*2\r\n$4\r\nINCR\r\n$1\r\nk\r\n";
        const GET: &[u8] = b"*2\r\n$3\r\nGET\r\n$1\r\nk\r\n";
        let pipeline = [SET, INCR, GET].concat();
        let worker_count = 8;
        let shard = crate::sharded_set_get_shard(b"k", worker_count);

        let mut staging = crate::ShardedTickStaging::new(worker_count);
        let parsed = crate::parse_sharded_set_get_batch(
            &pipeline,
            &ParserConfig::default(),
            crate::ShardedSetGetBatchParse {
                token: Token(71),
                first_sequence: 19,
                now_ms: 1,
                worker_count,
                command_limit: crate::MAX_FRAMES_PER_CLIENT_TICK,
            },
            &mut staging,
        )
        .expect("parse mixed single-key batch");

        assert_eq!(parsed.staged, 3);
        assert_eq!(parsed.consumed, pipeline.len());
        assert_eq!(parsed.staged_per_shard[shard], 3);
        let jobs = &staging.per_shard[shard];
        assert_eq!(jobs[0].sequence, 19);
        assert_eq!(jobs[2].sequence, 21);
        assert!(matches!(&jobs[0].command, ShardedSetGetCommand::Set { .. }));
        assert!(matches!(
            &jobs[1].command,
            ShardedSetGetCommand::SingleKey { .. }
        ));
        assert!(matches!(&jobs[2].command, ShardedSetGetCommand::Get { .. }));
        assert!(jobs.iter().all(|job| job.command.key() == b"k"));
    }

    /// Same-key commands must stay FIFO inside a shard even when the pipeline
    /// interleaves other shards between them — the property that makes
    /// per-key atomicity survive per-tick regrouping.
    #[test]
    fn sharded_staging_preserves_per_shard_fifo_under_interleaving() {
        let worker_count = 8;
        let mut pipeline = Vec::new();
        let mut expected: std::collections::BTreeMap<usize, Vec<u64>> =
            std::collections::BTreeMap::new();
        for i in 0..64u64 {
            let key = format!("k{i}");
            let frame = format!("*2\r\n$3\r\nGET\r\n${}\r\n{}\r\n", key.len(), key);
            pipeline.extend_from_slice(frame.as_bytes());
            let shard = crate::sharded_set_get_shard(key.as_bytes(), worker_count);
            expected.entry(shard).or_default().push(i);
        }
        assert!(
            expected.len() > 1,
            "fixture must actually spread across shards"
        );

        let mut staging = crate::ShardedTickStaging::new(worker_count);
        let parsed = crate::parse_sharded_set_get_batch(
            &pipeline,
            &ParserConfig::default(),
            crate::ShardedSetGetBatchParse {
                token: Token(9),
                first_sequence: 0,
                now_ms: 1,
                worker_count,
                command_limit: crate::MAX_FRAMES_PER_CLIENT_TICK,
            },
            &mut staging,
        )
        .expect("parse scattered pipeline");

        assert_eq!(parsed.staged, 64);
        assert_eq!(parsed.consumed, pipeline.len());
        for (shard, sequences) in expected {
            let got: Vec<u64> = staging.per_shard[shard]
                .iter()
                .map(|job| job.sequence)
                .collect();
            assert_eq!(got, sequences, "shard {shard} lost arrival order");
        }
    }

    #[test]
    fn sharded_pool_keeps_same_key_fifo_across_mixed_commands() {
        let poll = mio::Poll::new().expect("create test poll");
        let waker = std::sync::Arc::new(
            mio::Waker::new(poll.registry(), crate::BACKGROUND_WAKE_TOKEN)
                .expect("create shared background waker"),
        );
        let pool = ShardedSetGetPool::new(2, waker).expect("create two key shards");
        let jobs = vec![
            ShardedSetGetJob {
                token: Token(71),
                sequence: 0,
                now_ms: 1,
                command: ShardedSetGetCommand::Set {
                    key: b"k".to_vec(),
                    value: b"41".to_vec(),
                },
            },
            ShardedSetGetJob {
                token: Token(71),
                sequence: 1,
                now_ms: 1,
                command: ShardedSetGetCommand::SingleKey {
                    key: b"k".to_vec(),
                    encoded_frame: b"*2\r\n$4\r\nINCR\r\n$1\r\nk\r\n".to_vec(),
                },
            },
            ShardedSetGetJob {
                token: Token(71),
                sequence: 2,
                now_ms: 1,
                command: ShardedSetGetCommand::Get { key: b"k".to_vec() },
            },
        ];
        let shard = pool.shard_for_key(b"k");
        pool.try_enqueue_batch(shard, jobs)
            .unwrap_or_else(|_| panic!("enqueue same-key batch"));

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let completion_batch = loop {
            match pool.try_recv() {
                Ok(completion_batch) => break completion_batch,
                Err(std::sync::mpsc::TryRecvError::Empty) => {
                    assert!(
                        std::time::Instant::now() < deadline,
                        "timed out waiting for sharded completion batch"
                    );
                    thread::sleep(std::time::Duration::from_millis(1));
                }
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    panic!("sharded worker completion channel disconnected")
                }
            }
        };
        let completions = completion_batch.completions;
        assert_eq!(completions.len(), 3);
        assert_eq!(completions[0].sequence, 0);
        assert_eq!(completions[0].response, b"+OK\r\n");
        assert_eq!(completions[1].sequence, 1);
        assert_eq!(completions[1].response, b":42\r\n");
        assert_eq!(completions[2].sequence, 2);
        assert_eq!(completions[2].response, b"$2\r\n42\r\n");
        assert!(
            matches!(pool.try_recv(), Err(std::sync::mpsc::TryRecvError::Empty)),
            "three same-shard commands must produce one completion envelope"
        );
    }

