    #[test]
    fn borrowed_plain_zadd_packet_parser_accepts_canonical_score_member_packets() {
        let cfg = ParserConfig::default();

        let zadd = crate::parse_borrowed_plain_zadd_packet(
            b"*4\r\n$4\r\nzAdD\r\n$3\r\nkey\r\n$1\r\n1\r\n$6\r\nmember\r\n*1\r\n$4\r\nPING\r\n",
            &cfg,
        )
        .expect("canonical ZADD packet should parse");
        assert_eq!(zadd.key, b"key");
        assert_eq!(zadd.start, b"1", "the second bulk is the score");
        assert_eq!(zadd.end, b"member", "the third bulk is the member");
        assert_eq!(
            zadd.consumed,
            b"*4\r\n$4\r\nzAdD\r\n$3\r\nkey\r\n$1\r\n1\r\n$6\r\nmember\r\n".len()
        );

        // Scores are handed through as raw bytes for the executor to parse, so
        // the negative, fractional, exponent and infinity spellings all have to
        // survive the parse untouched.
        for score in [
            &b"-1"[..],
            &b"1.5"[..],
            &b"-0.0"[..],
            &b"1e3"[..],
            &b"+inf"[..],
            &b"-inf"[..],
            &b"notanumber"[..],
        ] {
            let mut packet = Vec::new();
            packet.extend_from_slice(b"*4\r\n$4\r\nZADD\r\n$1\r\nk\r\n$");
            packet.extend_from_slice(score.len().to_string().as_bytes());
            packet.extend_from_slice(b"\r\n");
            packet.extend_from_slice(score);
            packet.extend_from_slice(b"\r\n$1\r\nm\r\n");

            let parsed = crate::parse_borrowed_plain_zadd_packet(&packet, &cfg)
                .expect("ZADD parser must accept any well-framed score bulk");
            assert_eq!(
                parsed.start, score,
                "score bytes must reach the executor verbatim"
            );
            assert_eq!(parsed.end, b"m");
        }
    }

    #[test]
    fn borrowed_plain_zadd_packet_parser_defers_option_keywords_in_the_score_slot() {
        // `ZADD key NX member` is also a four-element packet, but its second
        // bulk is an OPTION, not a score. Serving it here would treat "NX" as a
        // score and "member" as the member — answering where redis reports a
        // wrong-number-of-arguments error, since the option form still needs a
        // score/member pair after the flag.
        //
        // The guard is case-insensitive, so the lowercase and mixed-case
        // spellings a real client may send must be excluded too.
        let cfg = ParserConfig::default();

        for keyword in [
            &b"NX"[..],
            &b"nx"[..],
            &b"Nx"[..],
            &b"XX"[..],
            &b"xx"[..],
            &b"GT"[..],
            &b"gt"[..],
            &b"LT"[..],
            &b"lt"[..],
            &b"CH"[..],
            &b"ch"[..],
            &b"INCR"[..],
            &b"incr"[..],
            &b"InCr"[..],
        ] {
            let mut packet = Vec::new();
            packet.extend_from_slice(b"*4\r\n$4\r\nZADD\r\n$1\r\nk\r\n$");
            packet.extend_from_slice(keyword.len().to_string().as_bytes());
            packet.extend_from_slice(b"\r\n");
            packet.extend_from_slice(keyword);
            packet.extend_from_slice(b"\r\n$1\r\nm\r\n");

            assert!(
                crate::parse_borrowed_plain_zadd_packet(&packet, &cfg).is_none(),
                "an option keyword in the score slot must stay on the generic parser"
            );
        }
    }

    #[test]
    fn borrowed_plain_zadd_packet_parser_only_excludes_keywords_from_the_score_slot() {
        // The exclusion is scoped to the score slot. A MEMBER legitimately
        // named NX or INCR is an ordinary sorted-set member and must still be
        // served by the fast path — over-broad filtering would silently push
        // valid traffic onto the slow path and, worse, suggest the guard is
        // about the packet rather than about the score position.
        let cfg = ParserConfig::default();

        for member in [&b"NX"[..], &b"incr"[..], &b"CH"[..]] {
            let mut packet = Vec::new();
            packet.extend_from_slice(b"*4\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$");
            packet.extend_from_slice(member.len().to_string().as_bytes());
            packet.extend_from_slice(b"\r\n");
            packet.extend_from_slice(member);
            packet.extend_from_slice(b"\r\n");

            let parsed = crate::parse_borrowed_plain_zadd_packet(&packet, &cfg)
                .expect("a member named like an option keyword is still a member");
            assert_eq!(parsed.start, b"1");
            assert_eq!(parsed.end, member);
        }
    }

    #[test]
    fn borrowed_plain_zadd_packet_parser_defers_siblings_shapes_and_limits() {
        let cfg = ParserConfig::default();

        // Four-byte four-element siblings. LSET and LREM are list mutations
        // with the identical key+arg+arg layout, so a prefix-only match would
        // add a sorted-set member in place of a list write.
        for other in [
            &b"*4\r\n$4\r\nLSET\r\n$1\r\nk\r\n$1\r\n0\r\n$1\r\nv\r\n"[..],
            &b"*4\r\n$4\r\nLREM\r\n$1\r\nk\r\n$1\r\n0\r\n$1\r\nv\r\n"[..],
            &b"*4\r\n$4\r\nHSET\r\n$1\r\nk\r\n$1\r\nf\r\n$1\r\nv\r\n"[..],
            &b"*4\r\n$4\r\nSADD\r\n$1\r\nk\r\n$1\r\na\r\n$1\r\nb\r\n"[..],
        ] {
            assert!(
                crate::parse_borrowed_plain_zadd_packet(other, &cfg).is_none(),
                "ZADD parser must reject a same-shape sibling command"
            );
        }

        assert!(
            crate::parse_borrowed_plain_zadd_packet(
                b"*04\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$1\r\nm\r\n",
                &cfg
            )
            .is_none(),
            "noncanonical multibulk length stays on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd_packet(
                b"*4\r\n$04\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$1\r\nm\r\n",
                &cfg
            )
            .is_none(),
            "noncanonical command bulk length stays on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd_packet(
                b"*4\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$1\r\nm\r\n",
                &ParserConfig {
                    max_array_len: 3,
                    ..ParserConfig::default()
                },
            )
            .is_none(),
            "array-limit errors stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd_packet(
                b"*4\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$1\r\nm\r\n",
                &ParserConfig {
                    max_bulk_len: 3,
                    ..ParserConfig::default()
                },
            )
            .is_none(),
            "command bulk-limit errors stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd_packet(
                b"*4\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$6\r\nmmmmmm\r\n",
                &ParserConfig {
                    max_bulk_len: 5,
                    ..ParserConfig::default()
                },
            )
            .is_none(),
            "member bulk-limit errors stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd_packet(
                b"*4\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm\r\n",
                &cfg
            )
            .is_none(),
            "malformed trailing bulk bodies stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd_packet(
                b"*3\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n",
                &cfg
            )
            .is_none(),
            "wrong-arity packets stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd_packet(b"*4\r\n$4\r\nZA", &cfg).is_none(),
            "packets truncated inside the command token stay on the generic parser"
        );
    }

    #[test]
    fn borrowed_plain_zadd2_packet_parser_binds_both_pairs_in_wire_order() {
        // Five same-shaped payload bulks (key, s1, m1, s2, m2). A parser that
        // read them out of order would still parse and still typecheck, and for
        // a sorted-set write that means scoring the wrong member. Distinct
        // lengths make the binding observable.
        let cfg = ParserConfig::default();

        let zadd2 = crate::parse_borrowed_plain_zadd2_packet(
            b"*6\r\n$4\r\nzAdD\r\n$3\r\nkey\r\n$1\r\n1\r\n$2\r\nm1\r\n$2\r\n22\r\n$3\r\nm22\r\n*1\r\n$4\r\nPING\r\n",
            &cfg,
        )
        .expect("canonical 2-pair ZADD packet should parse");
        assert_eq!(zadd2.key, b"key");
        assert_eq!(zadd2.s1, b"1", "second bulk is the first score");
        assert_eq!(zadd2.m1, b"m1", "third bulk is the first member");
        assert_eq!(zadd2.s2, b"22", "fourth bulk is the second score");
        assert_eq!(zadd2.m2, b"m22", "fifth bulk is the second member");
        assert_eq!(
            zadd2.consumed,
            b"*6\r\n$4\r\nzAdD\r\n$3\r\nkey\r\n$1\r\n1\r\n$2\r\nm1\r\n$2\r\n22\r\n$3\r\nm22\r\n"
                .len()
        );
    }

    #[test]
    fn borrowed_plain_zadd2_packet_parser_defers_option_keywords_in_the_first_score_slot() {
        // Same reasoning as the single-pair form: `ZADD key NX s m ...` puts an
        // OPTION where this parser expects the first score, and the option form
        // belongs to the generic path. Case-insensitive, so the lowercase
        // spellings are asserted too.
        let cfg = ParserConfig::default();

        for keyword in [
            &b"NX"[..],
            &b"nx"[..],
            &b"XX"[..],
            &b"xx"[..],
            &b"GT"[..],
            &b"gt"[..],
            &b"LT"[..],
            &b"lt"[..],
            &b"CH"[..],
            &b"ch"[..],
            &b"INCR"[..],
            &b"InCr"[..],
        ] {
            let mut packet = Vec::new();
            packet.extend_from_slice(b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$");
            packet.extend_from_slice(keyword.len().to_string().as_bytes());
            packet.extend_from_slice(b"\r\n");
            packet.extend_from_slice(keyword);
            packet.extend_from_slice(b"\r\n$2\r\nm1\r\n$1\r\n2\r\n$2\r\nm2\r\n");

            assert!(
                crate::parse_borrowed_plain_zadd2_packet(&packet, &cfg).is_none(),
                "an option keyword in the first score slot must stay on the generic parser"
            );
        }
    }

    #[test]
    fn borrowed_plain_zadd2_packet_parser_guards_only_the_first_score_slot() {
        // The guard is deliberately asymmetric and that asymmetry is CORRECT,
        // not an oversight worth "fixing". Redis only recognises ZADD options
        // before the first score, so once a score/member pair has been
        // consumed, a later NX is an ordinary score token — invalid as a float,
        // which the executor reports, exactly as redis does. Serving it here is
        // therefore right, and narrowing the guard to s1 is what makes the fast
        // path agree with the generic path about which inputs are errors.
        //
        // Members named after keywords are likewise just members.
        let cfg = ParserConfig::default();

        let later_score_keyword = crate::parse_borrowed_plain_zadd2_packet(
            b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm1\r\n$2\r\nNX\r\n$2\r\nm2\r\n",
            &cfg,
        )
        .expect("a keyword in the SECOND score slot is an ordinary score token");
        assert_eq!(later_score_keyword.s2, b"NX");

        let keyword_members = crate::parse_borrowed_plain_zadd2_packet(
            b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nNX\r\n$1\r\n2\r\n$4\r\nINCR\r\n",
            &cfg,
        )
        .expect("members named like option keywords are still members");
        assert_eq!(keyword_members.m1, b"NX");
        assert_eq!(keyword_members.m2, b"INCR");
    }

    #[test]
    fn borrowed_plain_zadd2_packet_parser_defers_siblings_shapes_and_limits() {
        let cfg = ParserConfig::default();

        // HSET with two field/value pairs is byte-identical through
        // `*6\r\n$4\r\n` — same arity, same five payload bulks, different data
        // type entirely. A four-member SADD is the same shape again. The
        // command compare is all that separates a hash or set write from a
        // sorted-set write.
        for other in [
            &b"*6\r\n$4\r\nHSET\r\n$1\r\nk\r\n$2\r\nf1\r\n$2\r\nv1\r\n$2\r\nf2\r\n$2\r\nv2\r\n"[..],
            &b"*6\r\n$4\r\nSADD\r\n$1\r\nk\r\n$1\r\na\r\n$1\r\nb\r\n$1\r\nc\r\n$1\r\nd\r\n"[..],
            &b"*6\r\n$4\r\nZREM\r\n$1\r\nk\r\n$1\r\na\r\n$1\r\nb\r\n$1\r\nc\r\n$1\r\nd\r\n"[..],
        ] {
            assert!(
                crate::parse_borrowed_plain_zadd2_packet(other, &cfg).is_none(),
                "the 2-pair ZADD parser must reject a same-shape sibling command"
            );
        }
        // Other pair counts belong elsewhere: one pair is the simple form, and
        // three pairs must reach the generic path rather than being served with
        // the third pair silently dropped.
        for packet in [
            &b"*4\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$1\r\nm\r\n"[..],
            &b"*8\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm1\r\n$1\r\n2\r\n$2\r\nm2\r\n$1\r\n3\r\n$2\r\nm3\r\n"[..],
        ] {
            assert!(
                crate::parse_borrowed_plain_zadd2_packet(packet, &cfg).is_none(),
                "pair counts other than two stay on their own paths"
            );
        }

        assert!(
            crate::parse_borrowed_plain_zadd2_packet(
                b"*06\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm1\r\n$1\r\n2\r\n$2\r\nm2\r\n",
                &cfg
            )
            .is_none(),
            "noncanonical multibulk length stays on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd2_packet(
                b"*6\r\n$04\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm1\r\n$1\r\n2\r\n$2\r\nm2\r\n",
                &cfg
            )
            .is_none(),
            "noncanonical command bulk length stays on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd2_packet(
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm1\r\n$1\r\n2\r\n$2\r\nm2\r\n",
                &ParserConfig {
                    max_array_len: 5,
                    ..ParserConfig::default()
                },
            )
            .is_none(),
            "array-limit errors stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd2_packet(
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm1\r\n$1\r\n2\r\n$2\r\nm2\r\n",
                &ParserConfig {
                    max_bulk_len: 3,
                    ..ParserConfig::default()
                },
            )
            .is_none(),
            "command bulk-limit errors stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd2_packet(
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm1\r\n$1\r\n2\r\n$6\r\nmmmmmm\r\n",
                &ParserConfig {
                    max_bulk_len: 5,
                    ..ParserConfig::default()
                },
            )
            .is_none(),
            "a trailing member over the bulk limit stays on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd2_packet(
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm1\r\n$1\r\n2\r\n$3\r\nm2\r\n",
                &cfg
            )
            .is_none(),
            "malformed trailing bulk bodies stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd2_packet(
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm1\r\n$1\r\n2\r\n",
                &cfg
            )
            .is_none(),
            "packets missing a declared pair element stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zadd2_packet(b"*6\r\n$4\r\nZA", &cfg).is_none(),
            "packets truncated inside the command token stay on the generic parser"
        );
    }

    // (frankenredis-f3nry) The fused arity-6 parser decides BETWEEN the two ZADD
    // readings on one pass. The oracle below is written out by hand from the ZADD
    // grammar rather than derived from the parser's own keyword list, so deleting
    // a guard in the parser fails a test instead of quietly changing what the
    // "expected" answer is.
    // (frankenredis-f3nry) The arity-5 fusion. Its routing oracle is the opposite
    // of the arity-6 one on INCR -- at length 5 INCR is a SERVED reading with its
    // own executor, at length 6 it must reach generic -- so the two tests together
    // pin that the guard is per-arity and not a blanket "INCR is special".
    #[test]
    fn borrowed_plain_zadd_arity5_parser_routes_flag_and_incr_readings() {
        use crate::BorrowedPlainZaddArity5Packet as Reading;
        let cfg = ParserConfig::default();

        #[derive(Debug, PartialEq)]
        enum Want {
            Flag,
            Incr,
            Generic,
        }

        let corpus: &[(&[u8], Want, &str)] = &[
            (
                b"*5\r\n$4\r\nZADD\r\n$1\r\nk\r\n$2\r\nXX\r\n$1\r\n5\r\n$2\r\nm1\r\n",
                Want::Flag,
                "one flag then a pair",
            ),
            (
                b"*5\r\n$4\r\nZADD\r\n$1\r\nk\r\n$2\r\ngt\r\n$1\r\n5\r\n$2\r\nm1\r\n",
                Want::Flag,
                "flags are case-insensitive",
            ),
            (
                b"*5\r\n$4\r\nZADD\r\n$1\r\nk\r\n$4\r\nINCR\r\n$1\r\n5\r\n$2\r\nm1\r\n",
                Want::Incr,
                "INCR is a served reading at this arity",
            ),
            (
                b"*5\r\n$4\r\nZADD\r\n$1\r\nk\r\n$4\r\nInCr\r\n$1\r\n5\r\n$2\r\nm1\r\n",
                Want::Incr,
                "INCR is case-insensitive too",
            ),
            // `ZADD k 1 a 2` is a score where an option must be: redis rejects it
            // as a syntax error, and neither reading may claim it.
            (
                b"*5\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$1\r\na\r\n$1\r\n2\r\n",
                Want::Generic,
                "a bare score in the option slot belongs to generic",
            ),
            (
                b"*5\r\n$4\r\nZADD\r\n$1\r\nk\r\n$2\r\nZZ\r\n$1\r\n5\r\n$2\r\nm1\r\n",
                Want::Generic,
                "an unknown keyword belongs to generic",
            ),
            (
                b"*5\r\n$5\r\nLPUSH\r\n$1\r\nk\r\n$2\r\nXX\r\n$1\r\n5\r\n$2\r\nm1\r\n",
                Want::Generic,
                "a different command at the same arity is not ZADD",
            ),
        ];

        for (packet, want, why) in corpus {
            let got = match crate::parse_borrowed_plain_zadd_arity5_packet(packet, &cfg) {
                Some(Reading::Flag(_)) => Want::Flag,
                Some(Reading::Incr(_)) => Want::Incr,
                None => Want::Generic,
            };
            assert_eq!(&got, want, "{why}");
        }
    }

    #[test]
    fn borrowed_plain_zadd_arity5_projections_partition_the_readings() {
        // Same partition property the arity-6 pair needs, and for the same reason:
        // the cascade calls these two projections at two different depths, so if
        // both could claim one packet the cascade and the floor arm would serve
        // different readings of it and each would look self-consistent.
        let cfg = ParserConfig::default();

        for packet in [
            &b"*5\r\n$4\r\nZADD\r\n$1\r\nk\r\n$2\r\nXX\r\n$1\r\n5\r\n$2\r\nm1\r\n"[..],
            &b"*5\r\n$4\r\nZADD\r\n$1\r\nk\r\n$4\r\nINCR\r\n$1\r\n5\r\n$2\r\nm1\r\n"[..],
            &b"*5\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$1\r\na\r\n$1\r\n2\r\n"[..],
        ] {
            let flag = crate::parse_borrowed_plain_zadd_flag_packet(packet, &cfg).is_some();
            let incr = crate::parse_borrowed_plain_zadd_incr_packet(packet, &cfg).is_some();
            assert!(
                !(flag && incr),
                "the two arity-5 readings must stay mutually exclusive"
            );
            let fused = match crate::parse_borrowed_plain_zadd_arity5_packet(packet, &cfg) {
                Some(crate::BorrowedPlainZaddArity5Packet::Flag(_)) => (true, false),
                Some(crate::BorrowedPlainZaddArity5Packet::Incr(_)) => (false, true),
                None => (false, false),
            };
            assert_eq!(
                (flag, incr),
                fused,
                "cascade projections must agree with the fused routing"
            );
        }
    }

    #[test]
    fn borrowed_plain_zadd_arity5_incr_binds_score_and_member_in_wire_order() {
        // The INCR reading returns a KeyRange packet, whose {start, end} are
        // {score, member}. Swapping them would still parse, still reply, and would
        // increment a member named "42" by whatever "m22" parses to.
        let cfg = ParserConfig::default();

        let packet = crate::parse_borrowed_plain_zadd_incr_packet(
            b"*5\r\n$4\r\nzAdD\r\n$3\r\nkey\r\n$4\r\nINCR\r\n$2\r\n42\r\n$3\r\nm22\r\n*1\r\n$4\r\nPING\r\n",
            &cfg,
        )
        .expect("the INCR reading should parse");
        assert_eq!(packet.key, b"key");
        assert_eq!(packet.start, b"42", "fourth bulk is the increment");
        assert_eq!(packet.end, b"m22", "fifth bulk is the member");
        assert_eq!(
            packet.consumed,
            b"*5\r\n$4\r\nzAdD\r\n$3\r\nkey\r\n$4\r\nINCR\r\n$2\r\n42\r\n$3\r\nm22\r\n".len(),
            "consumed must stop at this packet, not swallow the pipelined PING"
        );
    }

    #[test]
    fn borrowed_plain_zadd_arity6_parser_routes_each_reading_and_declines_incr() {
        use crate::BorrowedPlainZaddArity6Packet as Reading;
        let cfg = ParserConfig::default();

        #[derive(Debug, PartialEq)]
        enum Want {
            TwoPair,
            Flag2,
            Generic,
        }

        // (packet, what the ZADD grammar says arity 6 means, why)
        let corpus: &[(&[u8], Want, &str)] = &[
            (
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm1\r\n$1\r\n2\r\n$2\r\nm2\r\n",
                Want::TwoPair,
                "two score/member pairs",
            ),
            (
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$2\r\nGT\r\n$2\r\nCH\r\n$1\r\n5\r\n$2\r\nm1\r\n",
                Want::Flag2,
                "two flags then one pair",
            ),
            (
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$2\r\nnx\r\n$2\r\nch\r\n$1\r\n5\r\n$2\r\nm1\r\n",
                Want::Flag2,
                "flags are case-insensitive",
            ),
            // INCR replies with a BULK score, not an integer count. No borrowed
            // executor produces that reply, so every arity-6 form carrying INCR
            // must reach the generic dispatcher — in EITHER flag slot.
            (
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$4\r\nINCR\r\n$2\r\nCH\r\n$1\r\n5\r\n$2\r\nm1\r\n",
                Want::Generic,
                "INCR in the first option slot",
            ),
            (
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$2\r\nGT\r\n$4\r\nINCR\r\n$1\r\n5\r\n$2\r\nm1\r\n",
                Want::Generic,
                "INCR in the second option slot",
            ),
            (
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$4\r\nInCr\r\n$2\r\nCH\r\n$1\r\n5\r\n$2\r\nm1\r\n",
                Want::Generic,
                "INCR is case-insensitive too",
            ),
            // A flag followed by a non-flag is a syntax error in redis, not a
            // two-pair write: serving it here would invent a score slot.
            (
                b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$2\r\nNX\r\n$1\r\n1\r\n$1\r\na\r\n$1\r\n2\r\n",
                Want::Generic,
                "one flag then a score is a dangling-element error",
            ),
            (
                b"*6\r\n$4\r\nHSET\r\n$1\r\nk\r\n$2\r\nf1\r\n$2\r\nv1\r\n$2\r\nf2\r\n$2\r\nv2\r\n",
                Want::Generic,
                "a byte-identical sibling command is not ZADD",
            ),
        ];

        for (packet, want, why) in corpus {
            let got = match crate::parse_borrowed_plain_zadd_arity6_packet(packet, &cfg) {
                Some(Reading::TwoPair(_)) => Want::TwoPair,
                Some(Reading::Flag2(_)) => Want::Flag2,
                None => Want::Generic,
            };
            assert_eq!(&got, want, "{why}");
        }
    }

    #[test]
    fn borrowed_plain_zadd_arity6_parser_binds_the_flagged_reading_in_wire_order() {
        // The fused parser reuses the token it already read as EITHER flag1 or
        // s1. A fusion that re-read the wrong slice — or bound arg1 to the score
        // — would still typecheck and would still reply, with the wrong member
        // scored. Distinct bulk contents make the binding observable.
        let cfg = ParserConfig::default();

        let Some(crate::BorrowedPlainZaddArity6Packet::Flag2(packet)) =
            crate::parse_borrowed_plain_zadd_arity6_packet(
                b"*6\r\n$4\r\nzAdD\r\n$3\r\nkey\r\n$2\r\nGT\r\n$2\r\nCH\r\n$2\r\n42\r\n$3\r\nm22\r\n*1\r\n$4\r\nPING\r\n",
                &cfg,
            )
        else {
            panic!("the two-flag reading should parse");
        };
        assert_eq!(packet.key, b"key");
        assert_eq!(packet.flag1, b"GT", "third bulk is the first flag");
        assert_eq!(packet.flag2, b"CH", "fourth bulk is the second flag");
        assert_eq!(packet.score, b"42", "fifth bulk is the score");
        assert_eq!(packet.member, b"m22", "sixth bulk is the member");
        assert_eq!(
            packet.consumed,
            b"*6\r\n$4\r\nzAdD\r\n$3\r\nkey\r\n$2\r\nGT\r\n$2\r\nCH\r\n$2\r\n42\r\n$3\r\nm22\r\n"
                .len(),
            "consumed must stop at this packet, not swallow the pipelined PING"
        );
    }

    #[test]
    fn borrowed_plain_zadd_arity6_projections_partition_the_readings() {
        // The two cascade-facing parsers are projections of the fused one, and
        // the property that makes that safe is that they PARTITION: no arity-6
        // packet may be accepted by both, and whichever accepts one must agree
        // with the fused parser's routing. If a future edit lets both claim the
        // same packet, the cascade would serve whichever came first in the
        // else-if chain and the floor arm would serve the other — a split brain
        // no reply-equality gate could see, because each path is self-consistent.
        let cfg = ParserConfig::default();

        for packet in [
            &b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$1\r\n1\r\n$2\r\nm1\r\n$1\r\n2\r\n$2\r\nm2\r\n"[..],
            &b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$2\r\nGT\r\n$2\r\nCH\r\n$1\r\n5\r\n$2\r\nm1\r\n"[..],
            &b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$4\r\nINCR\r\n$2\r\nCH\r\n$1\r\n5\r\n$2\r\nm1\r\n"[..],
            &b"*6\r\n$4\r\nZADD\r\n$1\r\nk\r\n$2\r\nNX\r\n$1\r\n1\r\n$1\r\na\r\n$1\r\n2\r\n"[..],
        ] {
            let two_pair = crate::parse_borrowed_plain_zadd2_packet(packet, &cfg).is_some();
            let flag2 = crate::parse_borrowed_plain_zadd_flag2_packet(packet, &cfg).is_some();
            assert!(
                !(two_pair && flag2),
                "the two arity-6 readings must stay mutually exclusive"
            );
            let fused = match crate::parse_borrowed_plain_zadd_arity6_packet(packet, &cfg) {
                Some(crate::BorrowedPlainZaddArity6Packet::TwoPair(_)) => (true, false),
                Some(crate::BorrowedPlainZaddArity6Packet::Flag2(_)) => (false, true),
                None => (false, false),
            };
            assert_eq!(
                (two_pair, flag2),
                fused,
                "cascade projections must agree with the fused routing"
            );
        }
    }

    #[test]
    fn borrowed_plain_expire_setrange_zincrby_packet_parsers_accept_canonical_packets() {
        let cfg = ParserConfig::default();

        let expire = crate::parse_borrowed_plain_expire_packet(
            b"*3\r\n$6\r\neXpIrE\r\n$3\r\nkey\r\n$2\r\n60\r\n*1\r\n$4\r\nPING\r\n",
            &cfg,
        )
        .expect("canonical EXPIRE packet should parse");
        assert_eq!(expire.key, b"key");
        assert_eq!(expire.member, b"60", "the second bulk is the TTL");
        assert_eq!(
            expire.consumed,
            b"*3\r\n$6\r\neXpIrE\r\n$3\r\nkey\r\n$2\r\n60\r\n".len()
        );

        let setrange = crate::parse_borrowed_plain_setrange_packet(
            b"*4\r\n$8\r\nsEtRaNgE\r\n$3\r\nkey\r\n$2\r\n10\r\n$5\r\nvalue\r\n",
            &cfg,
        )
        .expect("canonical SETRANGE packet should parse");
        assert_eq!(setrange.key, b"key");
        assert_eq!(setrange.start, b"10", "the second bulk is the offset");
        assert_eq!(setrange.end, b"value", "the third bulk is the value");

        let zincrby = crate::parse_borrowed_plain_zincrby_packet(
            b"*4\r\n$7\r\nzInCrBy\r\n$3\r\nkey\r\n$3\r\n1.5\r\n$6\r\nmember\r\n",
            &cfg,
        )
        .expect("canonical ZINCRBY packet should parse");
        assert_eq!(zincrby.key, b"key");
        assert_eq!(zincrby.start, b"1.5", "the second bulk is the increment");
        assert_eq!(zincrby.end, b"member", "the third bulk is the member");
    }

    #[test]
    fn borrowed_plain_expire_packet_parser_defers_the_option_form() {
        // Redis 7 gave EXPIRE the NX/XX/GT/LT options, which make the command
        // conditional — it may now return 0 where the plain form returns 1. The
        // option form is four elements, so the fast path's `*3` prefix defers
        // it; that arity guard is the only thing preventing a conditional
        // expiry from being applied unconditionally.
        let cfg = ParserConfig::default();

        for option in [&b"NX"[..], &b"XX"[..], &b"GT"[..], &b"LT"[..], &b"nx"[..]] {
            let mut packet = Vec::new();
            packet.extend_from_slice(b"*4\r\n$6\r\nEXPIRE\r\n$1\r\nk\r\n$2\r\n60\r\n$");
            packet.extend_from_slice(option.len().to_string().as_bytes());
            packet.extend_from_slice(b"\r\n");
            packet.extend_from_slice(option);
            packet.extend_from_slice(b"\r\n");

            assert!(
                crate::parse_borrowed_plain_expire_packet(&packet, &cfg).is_none(),
                "the conditional EXPIRE form must stay on the generic parser"
            );
        }
    }

    #[test]
    fn borrowed_plain_expire_setrange_zincrby_packet_parsers_pass_numeric_args_through() {
        // TTLs, offsets and increments all reach their executors as raw bytes
        // and are parsed and range-checked there. Out-of-range and non-numeric
        // values must stay command-level errors rather than becoming parse
        // deferrals, or the fast path and the generic path would disagree about
        // which inputs are errors at all.
        let cfg = ParserConfig::default();

        for arg in [
            &b"-1"[..],
            &b"0"[..],
            &b"9223372036854775807"[..],
            &b"-9223372036854775808"[..],
            &b"notanumber"[..],
            &b""[..],
        ] {
            let mut expire = Vec::new();
            expire.extend_from_slice(b"*3\r\n$6\r\nEXPIRE\r\n$1\r\nk\r\n$");
            expire.extend_from_slice(arg.len().to_string().as_bytes());
            expire.extend_from_slice(b"\r\n");
            expire.extend_from_slice(arg);
            expire.extend_from_slice(b"\r\n");
            let parsed = crate::parse_borrowed_plain_expire_packet(&expire, &cfg)
                .expect("EXPIRE parser must accept any well-framed TTL bulk");
            assert_eq!(
                parsed.member, arg,
                "TTL bytes must reach the executor verbatim"
            );

            let mut zincrby = Vec::new();
            zincrby.extend_from_slice(b"*4\r\n$7\r\nZINCRBY\r\n$1\r\nk\r\n$");
            zincrby.extend_from_slice(arg.len().to_string().as_bytes());
            zincrby.extend_from_slice(b"\r\n");
            zincrby.extend_from_slice(arg);
            zincrby.extend_from_slice(b"\r\n$1\r\nm\r\n");
            let parsed = crate::parse_borrowed_plain_zincrby_packet(&zincrby, &cfg)
                .expect("ZINCRBY parser must accept any well-framed increment bulk");
            assert_eq!(
                parsed.start, arg,
                "increment bytes must reach the executor verbatim"
            );
        }
    }

    #[test]
    fn borrowed_plain_expire_setrange_zincrby_packet_parsers_reject_same_prefix_siblings() {
        let cfg = ParserConfig::default();

        // EXPIRE joins the six-letter *3 cohort already covered by
        // frankenredis-7vlrv, frankenredis-pg6jj and frankenredis-5w5kb.
        for other in [
            &b"*3\r\n$6\r\nAPPEND\r\n$1\r\nk\r\n$1\r\nv\r\n"[..],
            &b"*3\r\n$6\r\nGETSET\r\n$1\r\nk\r\n$1\r\nv\r\n"[..],
            &b"*3\r\n$6\r\nGETBIT\r\n$1\r\nk\r\n$1\r\n0\r\n"[..],
            &b"*3\r\n$6\r\nINCRBY\r\n$1\r\nk\r\n$1\r\n1\r\n"[..],
            &b"*3\r\n$6\r\nDECRBY\r\n$1\r\nk\r\n$1\r\n1\r\n"[..],
        ] {
            assert!(
                crate::parse_borrowed_plain_expire_packet(other, &cfg).is_none(),
                "EXPIRE parser must reject a same-shape sibling command"
            );
        }
        // GETRANGE is the sharp one for SETRANGE: same `*4\r\n$8\r\n` prefix,
        // same key+arg+arg layout, and a READ where SETRANGE is a WRITE. A
        // prefix-only match would mutate a string in response to a fetch.
        assert!(
            crate::parse_borrowed_plain_setrange_packet(
                b"*4\r\n$8\r\nGETRANGE\r\n$1\r\nk\r\n$1\r\n0\r\n$2\r\n-1\r\n",
                &cfg
            )
            .is_none(),
            "SETRANGE parser must reject the same-shape GETRANGE read"
        );
        assert!(
            crate::parse_borrowed_plain_setrange_packet(
                b"*4\r\n$8\r\nBITCOUNT\r\n$1\r\nk\r\n$1\r\n0\r\n$2\r\n-1\r\n",
                &cfg
            )
            .is_none(),
            "SETRANGE parser must reject the same-shape ranged BITCOUNT read"
        );
        // RESTORE shares ZINCRBY's `*4\r\n$7\r\n` prefix and is a
        // deserialising WRITE, so a mismatch there would score a member using a
        // serialised payload as the member name.
        assert!(
            crate::parse_borrowed_plain_zincrby_packet(
                b"*4\r\n$7\r\nRESTORE\r\n$1\r\nk\r\n$1\r\n0\r\n$3\r\npay\r\n",
                &cfg
            )
            .is_none(),
            "ZINCRBY parser must reject the same-shape RESTORE command"
        );
    }

    #[test]
    fn borrowed_plain_expire_setrange_zincrby_packet_parsers_defer_invalid_shapes_and_limits() {
        let cfg = ParserConfig::default();

        assert!(
            crate::parse_borrowed_plain_expire_packet(
                b"*03\r\n$6\r\nEXPIRE\r\n$1\r\nk\r\n$1\r\n1\r\n",
                &cfg
            )
            .is_none(),
            "noncanonical multibulk length stays on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_setrange_packet(
                b"*4\r\n$08\r\nSETRANGE\r\n$1\r\nk\r\n$1\r\n0\r\n$1\r\nv\r\n",
                &cfg
            )
            .is_none(),
            "noncanonical command bulk length stays on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zincrby_packet(
                b"*4\r\n$7\r\nZINCRBY\r\n$1\r\nk\r\n$1\r\n1\r\n$1\r\nm\r\n",
                &ParserConfig {
                    max_array_len: 3,
                    ..ParserConfig::default()
                },
            )
            .is_none(),
            "array-limit errors stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_setrange_packet(
                b"*4\r\n$8\r\nSETRANGE\r\n$1\r\nk\r\n$1\r\n0\r\n$1\r\nv\r\n",
                &ParserConfig {
                    max_bulk_len: 7,
                    ..ParserConfig::default()
                },
            )
            .is_none(),
            "command bulk-limit errors stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_setrange_packet(
                b"*4\r\n$8\r\nSETRANGE\r\n$1\r\nk\r\n$1\r\n0\r\n$9\r\nvvvvvvvvv\r\n",
                &ParserConfig {
                    max_bulk_len: 8,
                    ..ParserConfig::default()
                },
            )
            .is_none(),
            "value bulk-limit errors stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_expire_packet(
                b"*3\r\n$6\r\nEXPIRE\r\n$1\r\nk\r\n$2\r\n1\r\n",
                &cfg
            )
            .is_none(),
            "malformed trailing bulk bodies stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_zincrby_packet(
                b"*3\r\n$7\r\nZINCRBY\r\n$1\r\nk\r\n$1\r\n1\r\n",
                &cfg
            )
            .is_none(),
            "wrong-arity packets stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_setrange_packet(
                b"*4\r\n$8\r\nSETRANGE\r\n$1\r\nk\r\n$1\r\n0\r\n$1\r\nv\r",
                &cfg
            )
            .is_none(),
            "truncated packets stay on the generic parser until more bytes arrive"
        );
        assert!(
            crate::parse_borrowed_plain_expire_packet(b"*3\r\n$6\r\nEXP", &cfg).is_none(),
            "packets truncated inside the command token stay on the generic parser"
        );
    }

