    #[test]
    fn borrowed_plain_mset_packet_dispatcher_handles_multi_and_defers_limited_inputs() {
        let cfg = ParserConfig::default();
        assert!(
            crate::parse_borrowed_plain_mset_packet(
                b"*3\r\n$4\r\nMSET\r\n$1\r\na\r\n$1\r\n1\r\n",
                &cfg
            )
            .is_none(),
            "single-pair MSET stays on the generic wrong-arity path"
        );
        let input = b"*19\r\n$4\r\nmSeT\r\n$1\r\na\r\n$1\r\n1\r\n$1\r\nb\r\n$1\r\n2\r\n$1\r\nc\r\n$1\r\n3\r\n$1\r\nd\r\n$1\r\n4\r\n$1\r\ne\r\n$1\r\n5\r\n$1\r\nf\r\n$1\r\n6\r\n$1\r\ng\r\n$1\r\n7\r\n$1\r\nh\r\n$1\r\n8\r\n$1\r\ni\r\n$1\r\n9\r\n*1\r\n$4\r\nPING\r\n";
        let parsed = crate::parse_borrowed_plain_mset_packet(input, &cfg);
        assert!(
            matches!(&parsed, Some(crate::BorrowedPlainMsetPacket::Multi(_))),
            "nine-pair MSET uses the shipped multi-pair parser"
        );
        let parsed = parsed.expect("multi-pair packet");
        assert_eq!(parsed.pairs().len(), 9);
        assert_eq!(parsed.pairs()[0], (b"a".as_slice(), b"1".as_slice()));
        assert_eq!(parsed.pairs()[8], (b"i".as_slice(), b"9".as_slice()));
        assert_eq!(
            parsed.consumed(),
            input.len() - b"*1\r\n$4\r\nPING\r\n".len(),
            "the multi parser must leave the next pipeline frame unread"
        );
        assert!(
            crate::parse_borrowed_plain_mset_packet(
                b"*017\r\n$4\r\nMSET\r\n$1\r\na\r\n$1\r\n1\r\n$1\r\nb\r\n$1\r\n2\r\n$1\r\nc\r\n$1\r\n3\r\n$1\r\nd\r\n$1\r\n4\r\n$1\r\ne\r\n$1\r\n5\r\n$1\r\nf\r\n$1\r\n6\r\n$1\r\ng\r\n$1\r\n7\r\n$1\r\nh\r\n$1\r\n8\r\n",
                &cfg
            )
            .is_none(),
            "noncanonical multibulk length stays on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_mset_packet(
                b"*17\r\n$4\r\nMSET\r\n$1\r\na\r\n$1\r\n1\r\n$1\r\nb\r\n$1\r\n2\r\n$1\r\nc\r\n$1\r\n3\r\n$1\r\nd\r\n$1\r\n4\r\n$1\r\ne\r\n$1\r\n5\r\n$1\r\nf\r\n$1\r\n6\r\n$1\r\ng\r\n$1\r\n7\r\n$1\r\nh\r\n$1\r\n8\r\n",
                &ParserConfig {
                    max_array_len: 16,
                    ..ParserConfig::default()
                },
            )
            .is_none(),
            "array-limit errors stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_mset_packet(
                b"*19\r\n$4\r\nMSET\r\n$1\r\na\r\n$1\r\n1\r\n$1\r\nb\r\n$1\r\n2\r\n$1\r\nc\r\n$1\r\n3\r\n$1\r\nd\r\n$1\r\n4\r\n$1\r\ne\r\n$1\r\n5\r\n$1\r\nf\r\n$1\r\n6\r\n$1\r\ng\r\n$1\r\n7\r\n$1\r\nh\r\n$1\r\n8\r\n$1\r\ni\r\n$1\r\n9\r\n",
                &ParserConfig {
                    max_array_len: 18,
                    ..ParserConfig::default()
                },
            )
            .is_none(),
            "nine-pair array-limit errors stay on the generic parser"
        );
        assert!(
            crate::parse_borrowed_plain_mset_packet(
                b"*17\r\n$4\r\nMSET\r\n$2\r\na\r\n$1\r\n1\r\n$1\r\nb\r\n$1\r\n2\r\n$1\r\nc\r\n$1\r\n3\r\n$1\r\nd\r\n$1\r\n4\r\n$1\r\ne\r\n$1\r\n5\r\n$1\r\nf\r\n$1\r\n6\r\n$1\r\ng\r\n$1\r\n7\r\n$1\r\nh\r\n$1\r\n8\r\n",
                &cfg
            )
            .is_none(),
            "malformed bulk bodies stay on the generic parser"
        );
    }

    #[test]
    fn borrowed_plain_keyed_values18_packet_parser_accepts_canonical_write() {
        let input =
            b"*20\r\n$5\r\nlPuSh\r\n$4\r\nlist\r\n$1\r\na\r\n$1\r\nb\r\n$1\r\nc\r\n$1\r\nd\r\n$1\r\ne\r\n$1\r\nf\r\n$1\r\ng\r\n$1\r\nh\r\n$1\r\ni\r\n$1\r\nj\r\n$1\r\nk\r\n$1\r\nl\r\n$1\r\nm\r\n$1\r\nn\r\n$1\r\no\r\n$1\r\np\r\n$1\r\nq\r\n$1\r\nr\r\n*1\r\n$4\r\nPING\r\n";
        let (cmd, parsed) =
            crate::parse_borrowed_plain_keyed_values18_packet(input, &ParserConfig::default())
                .expect("canonical eighteen-value LPUSH packet should parse");

        assert_eq!(cmd, crate::PlainKeyedValuesCmd::Lpush);
        assert_eq!(parsed.key, b"list");
        assert_eq!(
            [
                parsed.v1, parsed.v2, parsed.v3, parsed.v4, parsed.v5, parsed.v6, parsed.v7,
                parsed.v8, parsed.v9, parsed.v10, parsed.v11, parsed.v12, parsed.v13, parsed.v14,
                parsed.v15, parsed.v16, parsed.v17, parsed.v18
            ],
            [
                b"a".as_slice(),
                b"b".as_slice(),
                b"c".as_slice(),
                b"d".as_slice(),
                b"e".as_slice(),
                b"f".as_slice(),
                b"g".as_slice(),
                b"h".as_slice(),
                b"i".as_slice(),
                b"j".as_slice(),
                b"k".as_slice(),
                b"l".as_slice(),
                b"m".as_slice(),
                b"n".as_slice(),
                b"o".as_slice(),
                b"p".as_slice(),
                b"q".as_slice(),
                b"r".as_slice()
            ]
        );
        assert_eq!(
            parsed.consumed,
            b"*20\r\n$5\r\nlPuSh\r\n$4\r\nlist\r\n$1\r\na\r\n$1\r\nb\r\n$1\r\nc\r\n$1\r\nd\r\n$1\r\ne\r\n$1\r\nf\r\n$1\r\ng\r\n$1\r\nh\r\n$1\r\ni\r\n$1\r\nj\r\n$1\r\nk\r\n$1\r\nl\r\n$1\r\nm\r\n$1\r\nn\r\n$1\r\no\r\n$1\r\np\r\n$1\r\nq\r\n$1\r\nr\r\n"
                .len()
        );

        let (cmd, parsed) = crate::parse_borrowed_plain_keyed_values18_packet(
            b"*20\r\n$4\r\nsAdD\r\n$3\r\nset\r\n$1\r\na\r\n$1\r\nb\r\n$1\r\nc\r\n$1\r\nd\r\n$1\r\ne\r\n$1\r\nf\r\n$1\r\ng\r\n$1\r\nh\r\n$1\r\ni\r\n$1\r\nj\r\n$1\r\nk\r\n$1\r\nl\r\n$1\r\nm\r\n$1\r\nn\r\n$1\r\no\r\n$1\r\np\r\n$1\r\nq\r\n$1\r\nr\r\n",
            &ParserConfig::default(),
        )
        .expect("canonical eighteen-value SADD packet should parse");
        assert_eq!(cmd, crate::PlainKeyedValuesCmd::Sadd);
        assert_eq!(parsed.key, b"set");
        assert_eq!(parsed.v18, b"r");
    }

