    #[test]
    fn borrowed_plain_object_refcount_args_match_exact_shape_only() {
        let args = [
            b"OBJECT".as_slice(),
            b"REFCOUNT".as_slice(),
            b"k".as_slice(),
        ];
        assert_eq!(
            super::borrowed_plain_object_refcount_args(&args),
            Some(b"k".as_slice())
        );

        let lower = [
            b"object".as_slice(),
            b"refcount".as_slice(),
            b"k".as_slice(),
        ];
        assert_eq!(
            super::borrowed_plain_object_refcount_args(&lower),
            Some(b"k".as_slice())
        );

        let encoding = [
            b"OBJECT".as_slice(),
            b"ENCODING".as_slice(),
            b"k".as_slice(),
        ];
        assert_eq!(super::borrowed_plain_object_refcount_args(&encoding), None);

        let trailing = [
            b"OBJECT".as_slice(),
            b"REFCOUNT".as_slice(),
            b"k".as_slice(),
            b"extra".as_slice(),
        ];
        assert_eq!(super::borrowed_plain_object_refcount_args(&trailing), None);
    }

    #[test]
    fn borrowed_plain_object_stat_packet_parser_accepts_idletime_and_freq() {
        let idletime = b"*3\r\n$6\r\noBjEcT\r\n$8\r\niDlEtImE\r\n$3\r\nkey\r\n*1\r\n$4\r\nPING\r\n";
        let parsed =
            crate::parse_borrowed_plain_object_stat_packet(idletime, &ParserConfig::default())
                .expect("canonical OBJECT IDLETIME key packet should parse");
        assert!(matches!(parsed.cmd, crate::PlainObjectStatCmd::Idletime));
        assert_eq!(parsed.key, b"key");
        assert_eq!(
            parsed.consumed,
            b"*3\r\n$6\r\noBjEcT\r\n$8\r\niDlEtImE\r\n$3\r\nkey\r\n".len()
        );

        let freq = b"*3\r\n$6\r\nOBJECT\r\n$4\r\nfReQ\r\n$1\r\nk\r\n";
        let parsed = crate::parse_borrowed_plain_object_stat_packet(freq, &ParserConfig::default())
            .expect("canonical OBJECT FREQ key packet should parse");
        assert!(matches!(parsed.cmd, crate::PlainObjectStatCmd::Freq));
        assert_eq!(parsed.key, b"k");
        assert_eq!(
            parsed.consumed,
            b"*3\r\n$6\r\nOBJECT\r\n$4\r\nfReQ\r\n$1\r\nk\r\n".len()
        );
    }

